/** Parses "1h30m", "45s", "2h5s" and similar into whole seconds. Units appear at most once, in h, m, s order. */
export function parseDuration(text) {
  if (typeof text !== "string") throw new TypeError("parseDuration(text) needs a string");
  const match = /^(?:(\d+)h)?(?:(\d+)m)?(?:(\d+)s)?$/.exec(text);
  if (!text || !match) throw new SyntaxError(`Not a duration: ${text}`);
  const [hours, minutes, seconds] = match.slice(1).map((part) => Number(part ?? 0));
  return hours * 3600 + minutes * 60 + seconds;
}
